import{z as i,x as n,o as t,c as p,q as r,j as B,D as e,d as A,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"训练循环的解剖","description":"","frontmatter":{"title":"训练循环的解剖","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-training-loop-anatomy.md","filePath":"llm/ti-training-loop-anatomy.md","lastUpdated":1791063341000}'),d={name:"llm/ti-training-loop-anatomy.md"};function m(D,a,h,C,c,f){const l=n("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="训练循环的解剖" tabindex="-1">训练循环的解剖 <a class="header-anchor" href="#训练循环的解剖" aria-label="Permalink to &quot;训练循环的解剖&quot;">​</a></h1><div class="epigraph"><p>训练基础设施的一切承诺，都是在「一个 step」这个最小完整单元上兑现的：预算按 step 记，状态按 step 断，观测按 step 落点。</p><footer>—— 据 Megatron-LM、DeepSpeed 与 OPT 训练日志等大规模预训练工程报告整理</footer></div><p><a href="/llm/edge-map">上一课</a>把端侧推理的决策收成一张七步账单，账算完之后不反悔；端侧课程的边界里明确留了一句：云端那一侧是另一条线。本课程「训练基础设施」就接这条线。逐个机制此前都写过——<a href="/llm/adamw">AdamW</a> 写更新式、<a href="/llm/pretrain-mixed-precision">混合精度</a>写数值、<a href="/llm/grad-clip-loss-spike">梯度裁剪</a>写爆炸——但它们怎么拼进一个 step、step 之外挂着哪些钩子、账从哪里记起，没有一处总装。本课做解剖，本课程后十四课默认你手里有这具骨架。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缺口不是任何一个机制的原理，而是它们的<strong>装配图</strong>。一个 step 里发生了什么、哪些状态被读、哪些被写、时间花在哪，若没有统一答案，三件事立刻失去锚点：MFU 没法分解（不知道慢在算、通信还是等数据）；故障没法归因（不知道尖峰该找数据队列还是找优化器）；钩子没法定价（不知道一次评测、一次存盘偷走了多少训练时间）。逐课学的机制像散落的器官，解剖要给出循环本体。</p><h3 id="一个-step-的部件清单" tabindex="-1">一个 step 的部件清单 <a class="header-anchor" href="#一个-step-的部件清单" aria-label="Permalink to &quot;一个 step 的部件清单&quot;">​</a></h3><p>一次迭代至少触碰六份状态：参数 \\(\\theta\\)、优化器状态（Adam 的 \\(m,v\\) 与步数）、学习率日程的进度、梯度缩放器、RNG（CPU、CUDA、数据侧）、数据游标。读侧进来一个微批，经<a href="/llm/grad-accum-microbatch">梯度累积</a>凑成全局批次；写侧出去一次参数更新。step 之间才是日志、评测、检查点三类钩子的位置——它们不改变轨迹，只读取轨迹。</p><p><span class="marginnote">术语翻译：RNG 就是随机数生成器——dropout、数据洗牌、初始化都靠它出「随机」数。之所以要随检查点一起存状态，是因为续训后若 RNG 从头开始，第 \\(t+1\\) 步的「随机」就和没断过时不一样，轨迹就接不上了。</span></p><p><span class="marginnote">以 4M token 的全局批次跑 1T token，全程约 25 万步；每步若被日志加 10 毫秒，整程多出约 42 分钟，而一次同步评测偷走几分钟就要乘上评测次数——钩子成本必须按全程折算，不是按单次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 step 写成显式阶段，每阶段标清在哪块硬件、多长时间：取批（数据队列是否 prefetch 就绪）、前向、反向、跨卡归约梯度、裁剪、优化器更新、日程推进、钩子。记录 \\(\\mathrm{MFU}=\\frac{\\text{单步有效浮点量}}{\\text{峰值浮点量}\\times\\text{步时}}\\) 时，步时要能拆成计算、通信、等数据三桶，否则优化无从下手。钩子写成分层预算：日志每步记标量（损失、梯度范数、吞吐），评测每 \\(N\\) 步在旁路数据上做且用独立 RNG，检查点每 \\(K\\) 步异步落盘。三者的节奏彼此错开，避免同一步同时付三笔账。</p>',11)),(t(),B(s,null,{default:e(()=>[o(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%95%B0%E6%8D%AE%E9%98%9F%E5%88%97%3A%20%E5%BE%AE%E6%89%B9%E5%B0%B1%E7%BB%AA%22%5D%20--%3E%20F%5B%22%E5%89%8D%E5%90%91%22%5D%0A%20%20F%20--%3E%20B%5B%22%E5%8F%8D%E5%90%91%E4%B8%8E%E5%B1%80%E9%83%A8%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20B%20--%3E%20R%5B%22%E8%B7%A8%E5%8D%A1%E6%A2%AF%E5%BA%A6%E5%BD%92%E7%BA%A6%22%5D%0A%20%20R%20--%3E%20C%5B%22%E8%A3%81%E5%89%AA%E4%B8%8E%E7%BC%A9%E6%94%BE%22%5D%0A%20%20C%20--%3E%20U%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E6%9B%B4%E6%96%B0%E4%B8%8E%E6%97%A5%E7%A8%8B%E6%8E%A8%E8%BF%9B%22%5D%0A%20%20U%20--%3E%20H%7B%22%E6%AD%A5%E5%8F%B7%E5%91%BD%E4%B8%AD%E9%92%A9%E5%AD%90%3F%22%7D%0A%20%20H%20--%3E%7C%E6%AF%8F%E6%AD%A5%7C%20LOG%5B%22%E8%AE%B0%E5%BD%95%E6%A0%87%E9%87%8F%E6%8C%87%E6%A0%87%22%5D%0A%20%20H%20--%3E%7C%E6%AF%8F%20N%20%E6%AD%A5%7C%20EV%5B%22%E6%97%81%E8%B7%AF%E8%AF%84%E6%B5%8B%2C%20%E7%8B%AC%E7%AB%8B%20RNG%22%5D%0A%20%20H%20--%3E%7C%E6%AF%8F%20K%20%E6%AD%A5%7C%20CK%5B%22%E5%BC%82%E6%AD%A5%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20H%20--%3E%7C%E5%90%A6%7C%20Q%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"为什么 step 能当记账单位：它是状态的天然一致点。钩子插在更新之后，读到的是「第 \\(t\\) 步末」的完整快照，参数与优化器状态不撕裂；日志、评测、存盘都以步号为坐标，跨子系统对齐才可能。反过来，任何声称「不影响训练」的旁路设施，验证标准也只有一条：同一份数据、同一串种子，开与关两种配置的逐步损失应当逐点重合。这给了基础设施一条可测试的契约，而不是一句口头保证。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易以为「只是读一下参数」的旁路操作必然无害——若评测同步挤进主计算流、或读取过程隐式调用了 RNG，轨迹就变了。「不改变轨迹」不是声明出来的，是开与关两种配置的逐步损失逐点重合验证出来的。")],-1)),(t(),B(s,null,{default:e(()=>[o(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CK%5B%22%E8%AF%BB%E5%8F%96%E6%A3%80%E6%9F%A5%E7%82%B9%3A%20%E7%AC%AC%20t%20%E6%AD%A5%E6%9C%AB%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20S1%5B%22%E5%8F%82%E6%95%B0%E4%B8%8E%E4%BC%98%E5%8C%96%E5%99%A8%E7%8A%B6%E6%80%81%20m%2C%20v%22%5D%0A%20%20CK%20--%3E%20S2%5B%22%E5%AD%A6%E4%B9%A0%E7%8E%87%E6%97%A5%E7%A8%8B%E8%BF%9B%E5%BA%A6%22%5D%0A%20%20CK%20--%3E%20S3%5B%22%E6%A2%AF%E5%BA%A6%E7%BC%A9%E6%94%BE%E5%99%A8%E7%8A%B6%E6%80%81%22%5D%0A%20%20CK%20--%3E%20S4%5B%22%E4%B8%89%E6%96%B9%20RNG%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20CK%20--%3E%20S5%5B%22%E6%95%B0%E6%8D%AE%E6%B8%B8%E6%A0%87%3A%20%E5%88%86%E7%89%87%E4%B8%8E%E5%81%8F%E7%A7%BB%22%5D%0A%20%20S1%20--%3E%20RES%5B%22%E5%85%AD%E4%BB%BD%E9%BD%90%3A%20%E4%BB%8E%E7%AC%AC%20t%2B1%20%E6%AD%A5%E6%97%A0%E7%BC%9D%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20S2%20--%3E%20RES%0A%20%20S3%20--%3E%20RES%0A%20%20S4%20--%3E%20RES%0A%20%20S5%20--%3E%20RES%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>时间预算同样以步为单位复利。训练一次 1T token 的账 = 步时 × 步数，而步时里的等待不会写在任何论文里：数据队列浅一档，GPU 就在每步里插进一段空转；钩子重一克，25 万步放大出小时级浪费。基础设施课的全部工程，都是在这条乘法里抢回分子。</p><p><span class="marginnote">数字实例：步时被等数据拖慢 5%——6 秒变 6.3 秒——单步看无所谓，25 万步合计多烧约 21 小时，按 256 卡折合五千多卡时。时间预算里没有「小」的浪费，只有还没乘以步数的浪费。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课解剖的是<strong>同步单作业循环</strong>：一个作业、一次迭代、全局同步点收尾。并行怎么把一个 step 摊到成百上千张卡上、同步点内部怎么重叠，属于下一课程「分布式训练深入」；RL 那种训练与采样交替的双引擎循环，属于后文 RL 训练系统；推理侧的步进与调度已在服务各课收束。另外，解剖不代替机制：损失为什么不降、数值为什么溢出，仍要到观测各课里找成因。</p><p>后课默认：谈数据、检查点、直方图、成本，落点都是这个 step 骨架上的某个部件或某段钩子；部件名与钩子节奏沿用本课的记法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一个 step 触碰六份状态：参数、优化器、日程、缩放器、RNG、数据游标；钩子只读不写。</li><li>步时拆成计算、通信、等数据三桶，MFU 的归因从分解开始。</li><li>日志每步、评测每 \\(N\\) 步、检查点每 \\(K\\) 步，节奏错开，成本按全程折算。</li><li>基础设施的契约是「不改变轨迹」：逐步损失可复现才算旁路透明。</li><li>出处：据 Megatron-LM（Shoeybi et al., 2019）、DeepSpeed/ZeRO（Rajbhandari et al., 2020）与 OPT 训练日志（Zhang et al., 2022）等工程报告整理。</li></ul>',7))])}const S=i(d,[["render",m]]);export{u as __pageData,S as default};
